const WINDOW = 5;
const FAILURE_RATE = 0.5; // 50%
const MIN_VOLUME = 3;
// 1 = failure, 0 = success. Deterministic sequence.
const calls = [0, 1, 0, 1, 1, 0, 1, 1];

const recent = [];
function record(outcome) {
  recent.push(outcome);
  if (recent.length > WINDOW) recent.shift();
  const volume = recent.length;
  const failures = recent.reduce((a, b) => a + b, 0);
  const rate = failures / volume;
  const trip = volume >= MIN_VOLUME && rate >= FAILURE_RATE;
  return { volume, failures, rate, trip };
}

for (let i = 0; i < calls.length; i++) {
  const r = record(calls[i]);
  console.log(
    `call ${i + 1}: vol=${r.volume} fails=${r.failures} rate=${r.rate.toFixed(2)} -> ${r.trip ? 'TRIP' : 'OK'}`
  );
}
